// Turns docs/wiki into Starlight pages (ADR-206). astro.config.mjs calls
// syncWiki() when the config loads, so `astro dev` and `astro build` always
// sync first. Generated files are gitignored.
//
// The source directory is $TELA_DOCS_DIR, or ../docs relative to site/. It
// holds wiki/ (the pages) and images/ (the screenshots).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const siteDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const pagesDir = path.join(siteDir, 'src/content/docs/docs');
const assetsDir = path.join(siteDir, 'src/assets/wiki');

const REPO = 'https://github.com/kuronosu/tela';
const RAW_IMAGES = 'https://raw.githubusercontent.com/kuronosu/tela/main/docs/images/';
const GENERATED_MARK = 'Code generated by "go run ./internal/gen/wikidoc"';

export function docsDir() {
	return path.resolve(siteDir, process.env.TELA_DOCS_DIR || '../docs');
}

/** The site route of a wiki page name (file name without .md). */
function routeOf(name) {
	if (name === 'Home') return '/docs/';
	if (name.startsWith('API-Reference-')) {
		return `/docs/reference/${name.slice('API-Reference-'.length).toLowerCase()}/`;
	}
	return `/docs/${name.toLowerCase()}/`;
}

/** The generated file of a wiki page, relative to pagesDir. */
function fileOf(name) {
	if (name === 'Home') return 'index.md';
	if (name.startsWith('API-Reference-')) {
		return `reference/${name.slice('API-Reference-'.length).toLowerCase()}.md`;
	}
	return `${name.toLowerCase()}.md`;
}

function writeIfChanged(file, data) {
	fs.mkdirSync(path.dirname(file), { recursive: true });
	if (fs.existsSync(file)) {
		const old = fs.readFileSync(file);
		if (Buffer.compare(old, Buffer.from(data)) === 0) return;
	}
	fs.writeFileSync(file, data);
}

/** Removes every file under dir that is not in keep (absolute paths), then empty dirs. */
function prune(dir, keep) {
	if (!fs.existsSync(dir)) return;
	for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
		const p = path.join(dir, entry.name);
		if (entry.isDirectory()) {
			prune(p, keep);
			if (fs.readdirSync(p).length === 0) fs.rmdirSync(p);
		} else if (!keep.has(p)) {
			fs.rmSync(p);
		}
	}
}

/** Plain text of a markdown heading: no code ticks, emphasis or link syntax. */
function plainTitle(md) {
	return md
		.replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1')
		.replace(/[`*_]/g, '')
		.trim();
}

/**
 * Applies fn to the prose of a markdown document: fenced code blocks and
 * inline code spans are masked so fn never sees them.
 */
function mapProse(text, fn) {
	const lines = text.split('\n');
	const out = [];
	let prose = [];
	let fence = null;
	const flush = () => {
		if (prose.length === 0) return;
		const masked = [];
		// Code spans may wrap across lines, so mask them over the whole run of prose.
		const joined = prose.join('\n').replace(/(`+)([\s\S]*?[^`])\1(?!`)/g, (m) => {
			masked.push(m);
			return `\u0000${masked.length - 1}\u0000`;
		});
		out.push(fn(joined).replace(/\u0000(\d+)\u0000/g, (_, i) => masked[Number(i)]));
		prose = [];
	};
	for (const line of lines) {
		const m = /^\s{0,3}(`{3,}|~{3,})/.exec(line);
		if (fence) {
			out.push(line);
			if (m && m[1][0] === fence[0] && m[1].length >= fence.length && /^\s*[`~]+\s*$/.test(line)) {
				fence = null;
			}
		} else if (m) {
			flush();
			fence = m[1];
			out.push(line);
		} else {
			prose.push(line);
		}
	}
	flush();
	return out.join('\n');
}

export function syncWiki() {
	const src = docsDir();
	const wikiDir = path.join(src, 'wiki');
	const imagesDir = path.join(src, 'images');
	if (!fs.existsSync(wikiDir)) {
		throw new Error(
			`sync-wiki: ${wikiDir} does not exist. Set TELA_DOCS_DIR to a directory that contains wiki/ and images/ (default: ../docs).`,
		);
	}

	const names = fs
		.readdirSync(wikiDir)
		.filter((f) => f.endsWith('.md') && !f.startsWith('_'))
		.map((f) => f.slice(0, -3))
		.sort();
	const known = new Set(names);

	// Images.
	const keepAssets = new Set();
	if (fs.existsSync(imagesDir)) {
		for (const f of fs.readdirSync(imagesDir)) {
			const dest = path.join(assetsDir, f);
			keepAssets.add(dest);
			const data = fs.readFileSync(path.join(imagesDir, f));
			writeIfChanged(dest, data);
		}
	}
	prune(assetsDir, keepAssets);

	// Pages.
	const keepPages = new Set();
	const problems = [];
	for (const name of names) {
		const file = `${name}.md`;
		let text = fs.readFileSync(path.join(wikiDir, file), 'utf8').replace(/\r\n/g, '\n');

		const generated = text.includes(GENERATED_MARK);
		text = text.replace(/^<!--.*?-->\n+/s, '');

		const h1 = /^#[ \t]+(.+?)[ \t]*#*[ \t]*\n/m.exec(text);
		if (!h1 || text.slice(0, h1.index).trim() !== '') {
			problems.push(`${file}: the page must start with a "# Title" line`);
			continue;
		}
		const title = plainTitle(h1[1]);
		text = text.slice(h1.index + h1[0].length).replace(/^\n+/, '');

		const dest = path.join(pagesDir, fileOf(name));
		const imgBase = path.relative(path.dirname(dest), assetsDir).split(path.sep).join('/');

		text = mapProse(text, (prose) => {
			// Images first (their targets are never wiki pages).
			prose = prose.replace(
				/(!\[[^\]]*\]\()([^)\s]+)((?:\s+"[^"]*")?\))/g,
				(m, pre, url, post) => {
					if (!url.startsWith(RAW_IMAGES)) return m;
					const img = url.slice(RAW_IMAGES.length);
					if (!keepAssets.has(path.join(assetsDir, img))) {
						problems.push(`${file}: image ${img} is not in ${imagesDir}`);
						return m;
					}
					return `${pre}${imgBase}/${img}${post}`;
				},
			);
			// Links to wiki pages.
			return prose.replace(/(\]\()([^)\s]+)((?:\s+"[^"]*")?\))/g, (m, pre, url, post) => {
				if (/^[a-z][a-z0-9+.-]*:/i.test(url) || url.startsWith('#') || url.startsWith('/')) return m;
				const [target, anchor] = url.split('#');
				if (!known.has(target)) {
					// Relative links that point at images or other files are left alone.
					if (/\.[a-z0-9]+$/i.test(target) || target.includes('/')) return m;
					problems.push(
						`${file}: link "${url}" looks like a wiki page but ${target}.md does not exist in ${wikiDir}`,
					);
					return m;
				}
				return `${pre}${routeOf(target)}${anchor ? '#' + anchor : ''}${post}`;
			});
		});

		const editUrl = generated ? 'false' : JSON.stringify(`${REPO}/edit/main/docs/wiki/${file}`);
		const page = `---\ntitle: ${JSON.stringify(title)}\neditUrl: ${editUrl}\n---\n\n${text}`;
		writeIfChanged(dest, page);
		keepPages.add(dest);
	}
	prune(pagesDir, keepPages);

	// Sidebar.
	const sidebarFile = path.join(wikiDir, '_Sidebar.md');
	if (!fs.existsSync(sidebarFile)) problems.push(`${sidebarFile} does not exist`);
	const { sidebar, listed } = problems.length ? { sidebar: [], listed: new Set() } : parseSidebar(sidebarFile, known, problems);

	if (problems.length) {
		throw new Error(`sync-wiki failed:\n  - ${problems.join('\n  - ')}`);
	}
	for (const name of names) {
		if (!listed.has(name)) {
			console.warn(`sync-wiki: warning: ${name}.md is not in _Sidebar.md; it is built but not in the sidebar`);
		}
	}
	return sidebar;
}

function parseSidebar(file, known, problems) {
	const sidebar = [];
	const listed = new Set();
	let group = null;
	for (const raw of fs.readFileSync(file, 'utf8').split('\n')) {
		const line = raw.trim();
		if (!line) continue;
		const bold = /^\*\*(.+)\*\*$/.exec(line);
		const link = /^(?:[-*]\s+)?(\*\*)?\[([^\]]+)\]\(([^)\s]+)\)(\*\*)?$/.exec(line);
		if (bold && !link) {
			group = { label: bold[1], items: [] };
			sidebar.push(group);
		} else if (link) {
			const isList = /^[-*]\s/.test(line);
			let [, , label, target] = link;
			let href = target;
			if (!/^[a-z][a-z0-9+.-]*:/i.test(target)) {
				if (!known.has(target)) {
					problems.push(`_Sidebar.md: "${target}" is not a wiki page`);
					continue;
				}
				listed.add(target);
				href = routeOf(target);
			}
			if (target === 'Home') label = 'Introduction';
			const entry = { label, link: href };
			if (isList && group) group.items.push(entry);
			else sidebar.push(entry);
		} else {
			problems.push(`_Sidebar.md: cannot read the line "${line}"`);
		}
	}
	return { sidebar: sidebar.map((e) => (e.items ? { label: e.label, items: e.items } : e)), listed };
}

/** Astro integration: re-syncs in dev when the source wiki or images change. */
export function wikiWatcher() {
	return {
		name: 'tela-wiki-watcher',
		hooks: {
			'astro:server:setup': ({ server, logger }) => {
				const src = docsDir();
				const dirs = [path.join(src, 'wiki'), path.join(src, 'images')];
				server.watcher.add(dirs);
				let timer;
				const onChange = (file) => {
					if (!dirs.some((d) => path.resolve(file).startsWith(d + path.sep))) return;
					clearTimeout(timer);
					timer = setTimeout(() => {
						try {
							syncWiki();
							logger.info('wiki synced');
						} catch (e) {
							logger.error(String(e.message || e));
						}
					}, 150);
				};
				for (const ev of ['add', 'change', 'unlink']) server.watcher.on(ev, onChange);
			},
		},
	};
}
